package com.dongqh.luckyhub.order;
import com.dongqh.luckyhub.catalog.dto.CreateProductCommand;import com.dongqh.luckyhub.catalog.enums.ProductType;import com.dongqh.luckyhub.catalog.service.CatalogService;import com.dongqh.luckyhub.coupon.dto.*;import com.dongqh.luckyhub.coupon.enums.CouponType;import com.dongqh.luckyhub.coupon.service.CouponService;import com.dongqh.luckyhub.inventory.channel.dto.*;import com.dongqh.luckyhub.inventory.channel.service.ChannelInventoryService;import com.dongqh.luckyhub.membership.dto.*;import com.dongqh.luckyhub.membership.enums.MembershipCardType;import com.dongqh.luckyhub.membership.service.MembershipService;import com.dongqh.luckyhub.order.dto.CreateCashOrderCommand;import com.dongqh.luckyhub.order.enums.CashOrderStatus;import com.dongqh.luckyhub.order.service.CashOrderService;import com.dongqh.luckyhub.rbac.entity.SysUser;import com.dongqh.luckyhub.rbac.mapper.SysUserMapper;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import java.time.LocalDateTime;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class CashOrderServiceTests { @Autowired CashOrderService orders;@Autowired CatalogService catalog;@Autowired CouponService coupons;@Autowired MembershipService memberships;@Autowired ChannelInventoryService inventory;@Autowired JdbcTemplate jdbc;@Autowired SysUserMapper users;Long userId,skuId,couponId;
 @BeforeEach void setup(){clean();SysUser u=new SysUser();u.setUsername("order-"+UUID.randomUUID());u.setPassword("x");u.setNickname("订单用户");u.setStatus(1);users.insert(u);userId=u.getId();String s=UUID.randomUUID().toString();var product=catalog.create(new CreateProductCommand("P-"+s,"100元商品",ProductType.PHYSICAL,null,null,"S-"+s,"默认",10000L,null,true,false));skuId=product.skus().get(0).id();inventory.initialize(new InitializeSkuStockCommand(skuId,10,"INIT-"+s));inventory.allocate(new AllocateChannelStockCommand(skuId,"MALL",10,"ALLOC-"+s));var mp=memberships.createProduct(new CreateMembershipProductCommand("M-"+s,"年卡","MEMBER",MembershipCardType.YEAR,365,100L,9000,0,10000));memberships.purchase(new PurchaseMembershipCommand("MB-"+s,mp.id(),userId));var ct=coupons.createTemplate(new CreateCouponTemplateCommand("C-"+s,"满80减20",CouponType.THRESHOLD,8000L,2000L,null,LocalDateTime.now().minusDays(1),LocalDateTime.now().plusDays(5),1,true));couponId=coupons.issue(new IssueCouponCommand("CI-"+s,"UC-"+s,ct.id(),userId)).id();}
 @AfterEach void tear(){clean();if(userId!=null)users.deleteById(userId);}
 @Test void createsSnapshotLocksCouponAndReservesMallStockIdempotently(){var c=new CreateCashOrderCommand("ORDER-70",skuId,1,couponId);var first=orders.create(userId,c);var repeated=orders.create(userId,c);assertThat(repeated.id()).isEqualTo(first.id());assertThat(first.status()).isEqualTo(CashOrderStatus.PENDING_PAYMENT);assertThat(first.originalAmountCent()).isEqualTo(10000L);assertThat(first.payableAmountCent()).isEqualTo(7000L);assertThat(coupons.getMine(userId,couponId).status().name()).isEqualTo("LOCKED");assertThat(inventory.get(skuId,"MALL").reservedStock()).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM mall_order WHERE order_no='ORDER-70'",Integer.class)).isOne();}
 private void clean(){if(jdbc==null)return;jdbc.update("DELETE FROM payment_order");jdbc.update("DELETE FROM mall_order");jdbc.update("DELETE FROM membership_grant_record");jdbc.update("DELETE FROM user_membership");jdbc.update("DELETE FROM membership_product");jdbc.update("DELETE FROM coupon_issue_record");jdbc.update("DELETE FROM user_coupon");jdbc.update("DELETE FROM coupon_template");jdbc.update("DELETE FROM inventory_ledger");jdbc.update("DELETE FROM inventory_reservation");jdbc.update("DELETE FROM inventory_channel_stock");jdbc.update("DELETE FROM sku_inventory");jdbc.update("DELETE FROM product_sku");jdbc.update("DELETE FROM product");}
}
